base.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_ami" "image" {
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-*"]
  }
}
resource "aws_instance" "web" {
  ami           = data.aws_ami.image.id
  instance_type = "t3.micro"
}

