terraform {
  backend "s3" {}
}
module "m" {
  source   = "./m"
  settings = sensitive({ host = "h" })
}

head.r/m/main.tf:
variable "settings" {
  type = object({
    host  = string
    cidrs = optional(list(string), ["0.0.0.0/0"])
  })
}
resource "aws_security_group_rule" "s" {
  type              = "ingress"
  security_group_id = "sg-1"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = try(var.settings.cidrs, [])
}
